def classes(n, m):
    p = list(range(n))
    def f(x):
        while p[x] != x: x = p[x]
        return x
    for i in range(n): p[f(i)] = f(n - 1 - i)
    for i in range(m): p[f(i)] = f(m - 1 - i)
    return len({f(i) for i in range(n)})
import itertools
def slow(n, m, k): return max(len(set(s)) for s in itertools.product(range(k), repeat=n) if s == s[::-1] and s[:m] == s[:m][::-1])
